// Only explicitly saved plans participate in guide calculations.
function wbEffective(c,r=routeContext(c)){try{const p=wbProjectValidate(wbApplied[c.id]),key=p.lanes[r]?r:!wbAvailable(c.id).includes(r)?p.continuationRoute:null;if(!key)return null;const full=p.lanes[key];if(wbPlanIssues(full).length)return null;const early=wbSplitPlan(full).early,d=r==='summary'||r==='救世篇'?full:{...full,stages:early};return d.stages.length?{p,r:key,d,full}:null;}catch{return null;}}
wbCharacterPlan=function(c,r){const effective=wbEffective(c,r),allowed=wbAvailable(c.id),key=allowed.includes(r)?r:allowed[0];return effective?{draft:effective.d,r:effective.r,custom:true}:{draft:wbPreset(c.id,key),r:key,custom:false};};
const originalProfileBuild=profileBuild,originalFinalBuild=finalBuild,originalInitialPlan=initialPlan,originalSkillTargets=qualificationTargets;
function wbCustomBuild(c,r){const e=wbEffective(c,r);if(!e)return null;const rows=wbCalculate(e.d).rows,pick=level=>rows.find(x=>x.end>level)||rows.at(-1),last=wbClass(e.d.stages.at(-1).classId),base=originalProfileBuild(c,r);return {...base,mid:[pick(20).className],upper:[pick(35).className],end:last.cn,focus:last.allowedSkills.join(' / '),priority:'按已保存的职业路线与等级培养。',goals:[requirement(wbClass(pick(20).className)),requirement(wbClass(pick(35).className))]};}
