const dossierNodeSel={};
function dossierStatsHTML(c,plan,result,i){
 if(i==null)return `<small>${result.fusion?'融合与接续后 · ':''}终点 Lv.${result.level} · ${result.baselineKnown?'永久属性期望':'成长增量（起始面板待确认）'}</small>${statPanel(result.baselineKnown?result.stats:result.gains,Object.keys(statNames),1)}`;
 const row=result.rows[i],cl=wbClass(plan.d.stages[i].classId),known=row.baselineKnown??plan.d.baselineKnown;
 return `<small>Lv.${row.end} · ${esc(cl.cn)} · ${known?'永久属性期望':'成长增量（起始面板待确认）'}</small>${statPanel(known?row.stats:row.gains,Object.keys(statNames),1)}<button type="button" class="text-button route-stats-reset" data-stats-reset="${escapeAttr(plan.r)}">回到终点 ↺</button>`;
}
function selectDossierNode(btn){
 const c=DB.characters.find(x=>x.id===btn.dataset.routeCharacter);if(!c)return;
 const key=c.id+'|'+btn.dataset.routeKey,i=Number(btn.dataset.routeNode);
 if(dossierNodeSel[key]===i){openReferenceDialog('class',btn.dataset.referenceId);return}
 dossierNodeSel[key]=i;
 document.querySelectorAll('#characterPage .path-node-selected').forEach(li=>li.classList.remove('path-node-selected'));
 btn.closest('li')?.classList.add('path-node-selected');
 const plan=wbDetailRoute(c),result=wbDetailCalculation(c,plan),bar=document.querySelector('#characterPage .route-final-stats');
 if(bar){bar.innerHTML=dossierStatsHTML(c,plan,result,i);bar.scrollIntoView({behavior:'smooth',block:'nearest'});}
}
function resetDossierStats(r){if(!activeCharacter)return;delete dossierNodeSel[activeCharacter+'|'+r];openCharacter(activeCharacter,true);}

let nodeEditor=null,nodeEditorAnchor=null;
