function positionNodeEditor(){if(!nodeEditor)return;if(!nodeEditorAnchor?.isConnected||!characterOpen()){closeNodeEditor();return;}const a=nodeEditorAnchor.getBoundingClientRect(),p=nodeEditor.getBoundingClientRect(),w=document.documentElement.clientWidth,h=window.visualViewport?.height||window.innerHeight,pad=12;nodeEditor.style.left=Math.max(pad,Math.min(a.left-20,w-p.width-pad))+'px';nodeEditor.style.top=Math.max(pad,Math.min(a.bottom+p.height+8<h?a.bottom+8:a.top-p.height-8,h-p.height-pad))+'px';}
function openNodeEditor(anchor){closeNodeEditor();closeClassQuick();const c=DB.characters.find(c=>c.id===anchor.dataset.inlineCharacter),plan=wbDetailRoute(c),i=Number(anchor.dataset.inlineEdit),d=wbValidate(plan.full),row=wbDetailCalculation(c,plan).rows[i];wbInline={characterId:c.id,r:plan.r,i,d,rowStart:row.start};nodeEditorAnchor=anchor;nodeEditor=document.createElement('section');nodeEditor.className='route-node-popover';nodeEditor.setAttribute('role','dialog');nodeEditor.setAttribute('aria-label','编辑'+wbClass(d.stages[i].classId).cn+'节点');nodeEditor.innerHTML=`<div class="node-editor-heading"><b>编辑职业节点</b><button data-inline-cancel aria-label="关闭节点编辑"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>`+wbInlineMarkup(c,i,d.stages[i],row);document.querySelector('#characterPage').appendChild(nodeEditor);anchor.setAttribute('aria-expanded','true');positionNodeEditor();bindClassPicker(nodeEditor);nodeEditor.querySelector('[data-class-picker-toggle]')?.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{if(nodeEditor&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeNodeEditor(true);}},true);
document.addEventListener('pointerdown',e=>{if(nodeEditor&&!nodeEditor.contains(e.target)&&!e.target.closest('[data-inline-edit]'))closeNodeEditor();},true);
